#include <bits/stdc++.h>
using namespace std;
#define int long long
void f(int idx, int &low ,int &high,vector<int>&arr){
    int r=arr.size()/3-idx;
    while(low < high) {
        int mid = (low+high)/2;
        
        int val = arr[idx + 2*mid] + arr[idx + 2*mid + 1] -3*arr[idx + 3*r - mid - 1];
        
        if(val > 0) low = mid+1;
        else high = mid;
    }
}
void solve() {
    int n;
    cin>>n;
    
    vector<int>arr(3*n);
    
    for(int i=0;i<3*n;i++){
        cin>>arr[i];
    }
    
    sort(arr.rbegin(),arr.rend());
    
    vector<int>pref(3*n+1,0);
    
    for(int i=1;i<=3*n;i++){
        pref[i]=pref[i-1]+arr[i-1];
    }
    
    int ans = 0;
    
    for(int idx=0; idx<=n; idx++) {
        int r = n - idx;
        
        int low = 0, high = r;
        
        f(idx,low,high,arr);
        int idx2 = low;
        
        int s1 = pref[idx + 2*idx2] - pref[idx];
        int s2  = pref[idx + 3*r - idx2] - pref[idx];
        
        int value = 6*pref[idx] + s1 + 3*s2;
        
        ans = max(ans,value);
    }
    
    cout << ans << "\n";
}

signed main() {
	// your code goes here
    int t;
    cin>>t;
    while(t--){
        solve();
    }
}
